excels.excel:

EXPORT WITH SHEET="销售提成计算表", HEADER=true,
    MAPPING={"a":"销售员","b":"销售区域","c":"销售目标","d":"实际销售额","e":"达成率","f":"提成比例","g":"提成金额"},
    FORMAT={"c":"#,##0.00","d":"#,##0.00","e":"0.00%","f":"0.00%","g":"#,##0.00"},
    FORMULAS={
        E2:'D2/C2',G2:'D2*F2',
        E3:'D3/C3',G3:'D3*F3',
        E4:'D4/C4',G4:'D4*F4',
        E5:'D5/C5',G5:'D5*F5',
        E6:'D6/C6',G6:'D6*F6',
        C7:'SUM(C2:C6)',D7:'SUM(D2:D6)',E7:'D7/C7',G7:'SUM(G2:G6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        E3:{color:red,bold:true}
    }
